router.post('/payments/:id/reverse',wrap(async(req,res)=>{const input=z.object({reason:z.string().trim().min(3).max(1000),date:z.coerce.date().optional()}).parse(req.body);const outcome=await atomic(async session=>{const payment=await BusinessPayment.findById(req.params.id).session(session);if(!payment)return {error:'missing' as const};if(payment.status!=='completed')return {error:'reversed' as const};const [reversal]=await BusinessPayment.create([{number:`RV-${Date.now()}-${randomUUID().slice(0,6).toUpperCase()}`,invoice:payment.invoice,client:payment.client,project:payment.project,amountMinor:payment.amountMinor,currency:payment.currency,date:input.date||new Date(),status:'reversed',reversesPayment:payment._id,notes:input.reason}],{session});payment.status='reversed';await payment.save({session});const invoice=await BusinessInvoice.findById(payment.invoice).session(session);if(invoice){const paid=await BusinessPayment.aggregate([{$match:{invoice:invoice._id,status:'completed'}},{$group:{_id:null,total:{$sum:'$amountMinor'}}}]).session(session);invoice.status=invoiceStatus(invoice.totalMinor,paid[0]?.total||0,invoice.dueDate);invoice.history.push({status:invoice.status,at:new Date(),note:`Payment reversed: ${input.reason}`});await invoice.save({session})}return {reversal,invoice};});if('error'in outcome)return res.status(outcome.error==='missing'?404:409).json({error:{message:outcome.error==='missing'?'Payment not found':'Only completed payments can be reversed.'}});await event(req,'payment.reverse',outcome.reversal,'Reversed a recorded payment').catch(()=>{});res.status(201).json({data:outcome})}));

