router.get('/notifications',wrap(async(req,res)=>{const {page,limit,skip}=pageArgs(req);const filter:any={archivedAt:null};if(req.query.unread==='true')filter.readAt=null;if(typeof req.query.category==='string')filter.category=req.query.category;const [data,total]=await Promise.all([BusinessNotification.find(filter).sort({createdAt:-1}).skip(skip).limit(limit).lean(),BusinessNotification.countDocuments(filter)]);res.json({data,meta:{page,limit,total,pages:Math.ceil(total/limit)}})}));router.patch('/notifications/:id/read',wrap(async(req,res)=>{const row=await BusinessNotification.findByIdAndUpdate(req.params.id,{readAt:new Date()},{new:true});if(!row)return res.status(404).json({error:{message:'Notification not found'}});res.json({data:row})}));router.post('/notifications/read-all',wrap(async(_req,res)=>{const result=await BusinessNotification.updateMany({archivedAt:null,readAt:null},{$set:{readAt:new Date()}});res.json({data:{modified:result.modifiedCount}})}));router.post('/notifications/archive',wrap(async(req,res)=>{const input=z.object({ids:z.array(id).min(1).max(100)}).parse(req.body);const result=await BusinessNotification.updateMany({_id:{$in:input.ids},archivedAt:null},{$set:{archivedAt:new Date()}});res.json({data:{archived:result.modifiedCount}})}));router.post('/notifications/prepare',wrap(async(req,res)=>{const [invoices,leads]=await Promise.all([BusinessInvoice.find({status:{$in:['Issued','Partially paid','Overdue']}}).select('number dueDate client').lean(),BusinessLead.find({followUpDate:{$lte:new Date()},status:{$nin:['Won','Lost']}}).select('name followUpDate').lean()]);let created=0;for(const invoice of invoices){const overdue=invoice.dueDate<new Date(),key=`invoice-${invoice._id}-${overdue?'overdue':'due'}`;const result=await BusinessNotification.updateOne({dedupeKey:key},{$setOnInsert:{kind:overdue?'invoice-overdue':'invoice-due',title:overdue?'Overdue invoice':'Invoice due',message:`Invoice ${invoice.number} ${overdue?'is overdue':'is due soon'}.`,relatedType:'Invoice',relatedId:String(invoice._id),dueAt:invoice.dueDate,deliveryStatus:'in-app'}},{upsert:true});if(result.upsertedCount)created++}for(const lead of leads){const key=`lead-followup-${lead._id}-${new Date(lead.followUpDate!).toISOString().slice(0,10)}`;const result=await BusinessNotification.updateOne({dedupeKey:key},{$setOnInsert:{kind:'lead-follow-up',title:'Lead follow-up due',message:`Follow up with ${lead.name}.`,relatedType:'Lead',relatedId:String(lead._id),dueAt:lead.followUpDate,deliveryStatus:'in-app'}},{upsert:true});if(result.upsertedCount)created++}res.json({data:{created,emailDelivery:'unavailable'}})}));

router.post('/notifications/prepare-all',wrap(async(_req,res)=>{const now=new Date(),week=new Date(now.getTime()+7*86400000),month=new Date(now.getTime()+30*86400000);let created=0;const put=async(dedupeKey:string,kind:string,title:string,message:string,relatedType:string,relatedId:string,dueAt:Date)=>{const result=await BusinessNotification.updateOne({dedupeKey},{$setOnInsert:{dedupeKey,kind,title,message,relatedType,relatedId,dueAt,deliveryStatus:'in-app'}},{upsert:true});created+=result.upsertedCount||0};const [proposals,projects,resources]=await Promise.all([BusinessProposal.find({status:{$in:['Sent','Viewed']},expiryDate:{$gte:now,$lte:week}}).select('number expiryDate').lean(),Project.find({targetLaunchDate:{$gte:now,$lte:week}}).select('name targetLaunchDate').lean(),BusinessInfrastructure.find({status:{$in:['active','maintenance']},renewalDate:{$gte:now,$lte:month}}).select('serviceName renewalDate').lean()]);for(const p of proposals)await put(`proposal-expiry-${p._id}-${p.expiryDate!.toISOString().slice(0,10)}`,'proposal-expiry','Proposal expiry reminder',`Proposal ${p.number} expires soon.`,'Proposal',String(p._id),p.expiryDate!);for(const p of projects)await put(`project-deadline-${p._id}-${p.targetLaunchDate!.toISOString().slice(0,10)}`,'project-deadline','Project deadline approaching',`Project ${p.name} has an upcoming target date.`,'Project',String(p._id),p.targetLaunchDate!);for(const r of resources)await put(`infrastructure-renewal-${r._id}-${r.renewalDate!.toISOString().slice(0,10)}`,'infrastructure-renewal','Infrastructure renewal approaching',`${r.serviceName} has an upcoming renewal date.`,'Infrastructure',String(r._id),r.renewalDate!);res.json({data:{created,emailDelivery:'unavailable'}})}));
router.get('/legacy-migration/preview',wrap(async(_req,res)=>{const modules=['clients','leads','services','proposals','invoices','finance','testing','technical-debt','deployments','infrastructure','notifications'];const rows=await WorkspaceRecord.find({module:{$in:modules}}).lean();const destination:Record<string,any>={BusinessClient,BusinessLead,BusinessService,BusinessTransaction,BusinessTechnicalDebt,BusinessTestCase,BusinessInfrastructure,BusinessDeployment,BusinessNotification};const groups:Record<string,{total:number;ready:number;migrated:number;review:number}>={};for(const row of rows){const stats=groups[row.module]||={total:0,ready:0,migrated:0,review:0};stats.total++;const mapped=mapLegacyBusinessRecord(row as any);if('issue'in mapped){stats.review++;continue}const Model=destination[mapped.collection];if(Model&&await Model.exists({legacySourceId:row._id}))stats.migrated++;else stats.ready++}res.json({data:{dryRun:true,groups,sourceRecordsPreserved:true,applyRequiresExplicitCommand:true}})}));
export default router;
